2.2 AndroidRuntime启动ZygoteInit 其中runtime就是AndroidRuntime类，我们来看看AndroidRuntime的start方法： /frameworks/base/core/jni/AndroidRuntime.cpp 1112 java/* 1113 * Start the Android runtime. This involves starting the virtual machine 1114 * and calling the &#34;static void main(String[] args)&#34; method in the class 1115 * named by &#34;className&#34;. 1116 * 1117 * Passes the main function two arguments, the class name and the specified 1118 * options string. 1119 */ 1120 void AndroidRuntime::start(const char* className, const Vector&lt;String8&gt;&amp; options, bool zygote) 1121 { ...... 1164 /* start the virtual machine */ 1165 JniInvocation jni_invocation; 1166 jni_invocation.Init(NULL); 1167 JNIEnv* env; 1168 if (startVm(&amp;mJavaVM, &amp;env, zygote) != 0) { 1169 return; 1170 } 1171 onVmCreated(env); 1172 1173 /* 1174 * Register android functions. 1175 */ 1176 if (startReg(env) &lt; 0) { 1177 ALOGE(&#34;Unable to register all android natives
&#34;); 1178 return; 1179 } ...... 1203 1204 /* 1205 * Start VM. This thread becomes the main thread of the VM, and will 1206 * not return until the VM exits. 1207 */ 1208 char* slashClassName = toSlashClassName(className != NULL ? className : &#34;&#34;); 1209 jclass startClass = env-&gt;FindClass(slashClassName); 1210 if (startClass == NULL) { 1211 ALOGE(&#34;JavaVM unable to locate class &#39;%s&#39;
&#34;, slashClassName); 1212 /* keep going */ 1213 } else { 1214 jmethodID startMeth = env-&gt;GetStaticMethodID(startClass, &#34;main&#34;, 1215 &#34;([Ljava/lang/String;)V&#34;); 1216 if (startMeth == NULL) { 1217 ALOGE(&#34;JavaVM unable to find main() in &#39;%s&#39;
&#34;, className); 1218 /* keep going */ 1219 } else { 1220 env-&gt;CallStaticVoidMethod(startClass, startMeth, strArray); 1226 } 1227 } ...... 1235 } 对虚拟机和JNI方法的一些注册后，通过CallStaticVoidMethod来调用传过来的类名的main函数，我们传递过来的类名是com.android.internal.os.ZygoteInit AndroidRuntime中主要做了这三件事： startVm() 创建虚拟机 startReg() 动态注册 java 调用 native 的 jni 反射调用 ZygoteInit 的 main()

git clone &ndash;recursive https://github.com/huang8604/huang8604.github.io.git 录屏传输 录屏方法 录屏原理 1 创建虚拟屏幕，把内容绘制到屏幕绑定的 surface 中 针对第三方的应用，由于缺少权限。 需要通过 MediaProjection 的方式创建 projectionManager = (MediaProjectionManager) getSystemService(MEDIA_PROJECTION_SERVICE); meidaProjection = projectionManager.getMediaProjection(resultCode,data); //创建前台通知 //mediac 创建的surface //创建虚拟屏幕 virtualDisplay = mediaProjection.createVirtualDisplay(&#34;name&#34;,width,height,dpi,flag..mirro,surface,null,null); 对于系统应用，可以直接创建虚拟屏幕 virtualDisplay = ((DisplayManager)getsystemservice(DISPLAY_SERVIcE)).createvirtualDisplay(&#34;Mainscreen&#34;, width, height, dpi,surface,flgs: 1 &lt; 10 | DisPlayManager.VIRTUAL_DISPLAY_FLAG PRESENTATION | DisPlayManage r.VIRTUAL_DISPLAY_FLKG_PUBLIC | DisPlayManager.VIRTUAL_DISPLAY_FLAG_OWN_CONTENT_ONLY); 2 surface 由 mediacodec 创建 3 把 surface 内容输入到 MediaCodec，然后编码 MediaFormat format = createFormate(... bit,fps,); MediaCodec codec = createMediaCodec(); SurfactControl.createDisplay(); configure(codec,format);//codec.configure(format) Surface surface = codec.createInputSurface(); setDisplaySurface(display,surface,...) codec.start(); try{ //开启循环 alive = encode(codec,fd); code.stop(); } finally{ destoryDisplay(diaplay); codec.release(); surface.release(); } private boolean encode(MediaCodec codec, FileDescriptor fd) throws IOException { boolean eof = false; MediaCodec.BufferInfo bufferInfo = new MediaCodec.BufferInfo(); while (!consumeRotationChange() &amp;&amp; !eof) { int outputBufferId = codec.dequeueOutputBuffer(bufferInfo, -1); eof = (bufferInfo.flags &amp; MediaCodec.BUFFER_FLAG_END_OF_STREAM) != 0; try { if (consumeRotationChange()) { // must restart encoding with new size break; } if (outputBufferId &gt;= 0) { ByteBuffer codecBuffer = codec.getOutputBuffer(outputBufferId); if (sendFrameMeta) {//写入文件头 writeFrameMeta(fd, bufferInfo, codecBuffer.remaining()); } //写入帧数据 IO.writeFully(fd, codecBuffer); } } finally { if (outputBufferId &gt;= 0) { codec.releaseOutputBuffer(outputBufferId, false); } } } return !eof; } private static void setDisplaySurface(IBinder display, Surface surface, int orientation, Rect deviceRect, Rect displayRect, int layerStack) { SurfaceControl.openTransaction(); try { SurfaceControl.setDisplaySurface(display, surface); SurfaceControl.setDisplayProjection(display, orientation, deviceRect, displayRect); SurfaceControl.setDisplayLayerStack(display, layerStack); } finally { SurfaceControl.closeTransaction(); } } private static MediaCodec (Codec codec, String encoderName) throws IOException, ConfigurationException { if (encoderName != null) { Ln.d(&#34;Creating encoder by name: &#39;&#34; + encoderName + &#34;&#39;&#34;); try { return MediaCodec.createByCodecName(encoderName); } catch (IllegalArgumentException e) { Ln.e(&#34;Video encoder &#39;&#34; + encoderName + &#34;&#39; for &#34; + codec.getName() + &#34; not found
&#34; + LogUtils.buildVideoEncoderListMessage()); throw new ConfigurationException(&#34;Unknown encoder: &#34; + encoderName); } catch (IOException e) { Ln.e(&#34;Could not create video encoder &#39;&#34; + encoderName + &#34;&#39; for &#34; + codec.getName() + &#34;
&#34; + LogUtils.buildVideoEncoderListMessage()); throw e; } } try { MediaCodec mediaCodec = MediaCodec.createEncoderByType(codec.getMimeType()); Ln.d(&#34;Using video encoder: &#39;&#34; + mediaCodec.getName() + &#34;&#39;&#34;); return mediaCodec; } catch (IOException | IllegalArgumentException e) { Ln.e(&#34;Could not create default video encoder for &#34; + codec.getName() + &#34;
&#34; + LogUtils.buildVideoEncoderListMessage()); throw e; } } 录屏保存为文件 String rootDir = Applistion.getInstance().getExternalCacheDir()+&#34;...&#34;; File file = new File(path+&#34;test.h264&#34;); FileOutputStream fileOutputStream = null; fileOutputStream = new FileOutputStream(file); fileOutputStream.write(data); fileOutstream.flush(); fileOutStream.close(); fileOutStream = null; file = null; 录屏数据编码传输 服务端 ServerSocket mServer = null; Socket mSoc

